alter table public.st_v2_reactions drop constraint st_v2_reactions_reaction_check,
  add constraint st_v2_reactions_reaction_check check(char_length(reaction) between 1 and 80);

alter table public.st_v5_profile_details add column share_last_seen boolean not null default false;

create function public.st_v5_set_last_seen(p_enabled boolean)
returns void language plpgsql security definer set search_path='' as $$
begin
  perform sectalk_private.limit_action('v5_last_seen_settings',10);
  if p_enabled is null then raise exception 'Choose a visibility setting'; end if;
  insert into public.st_v5_profile_details(user_id,share_last_seen) values(auth.uid(),p_enabled)
    on conflict(user_id) do update set share_last_seen=excluded.share_last_seen;
end $$;
revoke all on function public.st_v5_set_last_seen(boolean) from public,anon,authenticated;
grant execute on function public.st_v5_set_last_seen(boolean) to authenticated;

create or replace function public.st_v5_last_seen(p_chat uuid)
returns timestamptz language sql stable security definer set search_path='' as $$
  select p.expires_at-interval '100 seconds'
  from public.st_chats c join public.st_v3_presence p on p.user_id=
    case when c.member_a=auth.uid() then c.member_b else c.member_a end
  join public.st_v5_profile_details settings on settings.user_id=p.user_id and settings.share_last_seen
  where c.id=p_chat and auth.uid() in(c.member_a,c.member_b) and c.status='accepted'
    and sectalk_private.open_pair(c.member_a,c.member_b) and p.state<>'offline'
    and p.expires_at>now()-interval '7 days'
$$;

create or replace function public.st_v2_react(p_message uuid,p_reaction text,p_enabled boolean)
returns void language plpgsql security definer set search_path='' as $$
declare item public.st_messages; actor uuid:=auth.uid(); parts text[];
begin
  perform sectalk_private.limit_action('v2_reaction',40);
  select * into item from public.st_messages where id=p_message and revoked_at is null for update;
  if not found or not sectalk_private.st_v2_chat_write(item.chat_id,actor) then raise exception 'Conversation unavailable'; end if;
  if p_enabled is null or p_reaction is null or char_length(p_reaction) not between 1 and 80 then
    raise exception 'Choose an emoji reaction';
  end if;
  if not p_enabled then
    delete from public.st_v2_reactions where message_id=p_message and user_id=actor and reaction=p_reaction;
    return;
  end if;
  if exists(select 1 from public.st_v2_reactions where message_id=p_message and user_id=actor and reaction=p_reaction) then return; end if;
  if not exists(select 1 from sectalk_private.st_v5_reaction_catalog where collection='native' and value=p_reaction) then
    parts:=regexp_match(p_reaction,'^\[\[st:([^|]+)\|([^|]+)\]\]$');
    if parts is null or not exists(select 1 from sectalk_private.st_v5_reaction_catalog where collection='base' and value=parts[1])
      or not exists(select 1 from sectalk_private.st_v5_reaction_catalog where collection='badge' and value=parts[2])
      then raise exception 'Choose a reaction from the SecTalk emoji picker'; end if;
  end if;
  if (select count(*) from public.st_v2_reactions where message_id=p_message and user_id=actor)>=8
    then raise exception 'Remove a reaction before adding more'; end if;
  insert into public.st_v2_reactions(message_id,chat_id,user_id,reaction) values(p_message,item.chat_id,actor,p_reaction);
end $$;
